PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),created_at INTEGER NOT NULL);
CREATE TABLE roles(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE);
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id),role_id TEXT NOT NULL REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE subjects(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL);
CREATE TABLE topics(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id),title TEXT NOT NULL);
CREATE INDEX topics_subject_idx ON topics(subject_id);
CREATE TABLE questions(id TEXT PRIMARY KEY,topic_id TEXT NOT NULL REFERENCES topics(id),status TEXT NOT NULL CHECK(status IN ('draft','active','archived')));
CREATE INDEX questions_topic_status_idx ON questions(topic_id,status);
CREATE TABLE question_options(id TEXT PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id),stable_option_id TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(question_id,stable_option_id));
CREATE INDEX question_options_question_idx ON question_options(question_id);
CREATE TABLE exams(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id),title TEXT NOT NULL);
CREATE TABLE exam_versions(id TEXT PRIMARY KEY,exam_id TEXT NOT NULL REFERENCES exams(id),version_number INTEGER NOT NULL CHECK(version_number>0),content_hash TEXT NOT NULL,published_at INTEGER,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','revoked')),UNIQUE(exam_id,version_number),CHECK(status='draft' OR published_at IS NOT NULL));
CREATE TABLE exam_items(id TEXT PRIMARY KEY,exam_version_id TEXT NOT NULL REFERENCES exam_versions(id),position INTEGER NOT NULL CHECK(position>=0),question_snapshot_json TEXT NOT NULL CHECK(json_valid(question_snapshot_json)),answer_key_private_json TEXT NOT NULL CHECK(json_valid(answer_key_private_json)),UNIQUE(exam_version_id,position));
CREATE INDEX exam_items_version_idx ON exam_items(exam_version_id,position);
CREATE TRIGGER immutable_published_exam BEFORE UPDATE ON exam_versions WHEN OLD.published_at IS NOT NULL AND (NEW.exam_id<>OLD.exam_id OR NEW.version_number<>OLD.version_number OR NEW.content_hash<>OLD.content_hash OR NEW.published_at<>OLD.published_at OR NEW.status NOT IN ('published','revoked')) BEGIN SELECT RAISE(ABORT,'published version immutable'); END;
CREATE TRIGGER no_delete_published_exam BEFORE DELETE ON exam_versions WHEN OLD.published_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'published version immutable'); END;
CREATE TRIGGER no_edit_published_item BEFORE UPDATE ON exam_items WHEN (SELECT published_at FROM exam_versions WHERE id=OLD.exam_version_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'published items immutable'); END;
CREATE TRIGGER no_delete_published_item BEFORE DELETE ON exam_items WHEN (SELECT published_at FROM exam_versions WHERE id=OLD.exam_version_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'published items immutable'); END;
CREATE TRIGGER no_add_published_item BEFORE INSERT ON exam_items WHEN (SELECT published_at FROM exam_versions WHERE id=NEW.exam_version_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'published items immutable'); END;
